  {
   "id": "template:animal",
   "family": "template",
   "key": "animal",
   "concept": "generation",
   "source": {
    "file": "settings/fantasy/templates.json"
   },
   "definition": {
    "alignment": "neutral",
    "challenging": false,
    "gender": "=oneOf(male, female, neutral)",
    "background": "=oneOf(wild, trained)",
    "hometown": "the wilds",
    "hair": "=oneOf(black, white, brown, gray, spotted, striped)",
    "eye_color": "=oneOf(brown, blue, green, amber)",
    "personality": "=oneOf(aggressive, loyal, timid, curious, playful, fierce)",
    "terrain": "=oneOf(forest, cave, swamp, mountain, snow, desert)",
    "race": "=oneOf(goblin, kobold, orc, human, ogre, troll, dragon, human, elf, dwarf, halfling, gnome, fae, draconic, insectoid, birdfolk, duergar, sylph, undine, catfolk, gnoll, lizardfolk, half_orc, half_elf)",
    "age": "=5+1d10",
    "animal_type": "=lookup(companionType, #race)",
    "forename": "=lookupUnique(companionName, #animal_type)",
    "animal_aspect": "=lookup(creatureAspectTypes, if(#challenging, oneOf(rare, legendary), oneOf(common, uncommon)))",
    "class": "=capitalize(#terrain) + ' ' + capitalize(#animal_type)",
    "kind": "=#background != 'wild' ? capitalize(#background) : ''",
    "name": "=(#animal_aspect != 'wildtype' ? capitalize(#animal_aspect) + ' ' : '') + capitalize(#animal_type)",
    "_statBase": 3,
    "level": 1,
    "str": "=#_statBase+round(#level/8)",
    "dex": "=#_statBase+round(#level/8)",
    "con": "=#_statBase+round(#level/8)",
    "int": "=#_statBase+round(#level/8)",
    "wis": "=#_statBase+round(#level/8)",
    "cha": "=#_statBase+round(#level/8)",
    "*typeOverlay": "=lookup(animalKind, #animal_type)",
    "maximumHitPoints": "=#hp",
    "equipment": "=gen(equipment)",
    "abilities": [
     "melee",
     "defend",
     "flee"
    ],
    "xp": "=10*#level",
    "gp": 0,
    "*terrainModifier": "=lookup(terrainModifier, #terrain)",
    "*aspectModifier": "=lookup(creatureAspects, #animal_aspect)",
    "hp": "=#maximumHitPoints",
    "traits": [],
    "!remove": [
     "race"
    ]
   },
   "name": "=(#animal_aspect != 'wildtype' ? capitalize(#animal_aspect) + ' ' : '') + capitalize(#animal_type)",
   "description": "=oneOf(black, white, brown, gray, spotted, striped)",
   "references": [],
   "features": []
  },
  {
   "id": "template:boss_room",
   "family": "template",
   "key": "boss_room",
   "concept": "generation",
   "source": {
    "file": "settings/fantasy/templates.json"
   },
   "definition": {
    "_targetCr": 1,
    "depth": 0,
    "race": "goblin",
    "challenging": true,
    "difficultyTier": "=min(5, max(2,round(1 + #_targetCr / 3)))",
    "__building_type": "=oneOf(temple, fortress, library, tomb, mine)",
    "building_type": "tomb",
    "room_type": "=oneOf(throne_room, lair, altar)",
    "narrative": "=lookup(roomNarrative, #room_type)",
    "room_size": "=oneOf(medium, large, enormous, huge, colossal)",
    "targetCr": "=#_targetCr + round(#depth/3)",
    "_npcCount": 1,
    "_companionCount": 1,
    "_monsterCount": 1,
    "treasure": "=sample(lookup(treasure, oneOf(minor, major)), 2d4)",
    "npc_type": "=lookup(bossNpcTypesForDungeon, #building_type)",
    "boss_encounter": "=gen(encounter)",
    "decor": "=lookup(roomDecoration, 1d100)",
    "gear": "=gather(masterGear, 1d3 + 2)",
