data/rulesets/adventure.kyr:
Module adventure_rules "Small campaign rules" {
  Kind group. Kind place. Kind good. Kind stock. Kind pressure. Kind clock.
  Relation at(entity, place) exclusive.
  Relation route(place, place).
  Relation closed(place).
  Relation denied(group, place, place).
  Relation footway(place, place).
  Relation gate(group, place, place).
  Relation gatekeeper(group).
  Relation distinct(group, group).
  Relation able(group).
  Relation dead(group).
  Relation released(group).
  Relation sated(group).
  Relation acceptsFood(group).
  Relation carrying(group, good) exclusive.
  Relation unladen(group).
  Relation mayCollect(group, stock).
  Relation job(stock, good).
  Relation hostile(group, group).
  Relation recorded(pressure).
  Measure quantity(entity, good).
  Measure received(group).
  Measure claim(group).
  Measure mercy(group).
  Measure fee(stock).
  Measure required(stock, good).
  Measure watch(clock).
  Measure urgentAt(clock).
  Measure deficit(pressure).
  Query paid(who: group) means received(who) >= claim(who).
  Query releaseAllowed(who: group) means paid(who)
    or (acceptsFood(who) and sated(who)) or watch(clock) >= mercy(who).
  Goal false.

  Action wait(actor: group) "Wait" {
    Requires able(actor). Time 1.
  }
  Action travel(actor: group, origin: place, destination: place) "Travel to {destination}" {
    Result "You follow the route and arrive at the next place. People and dangers continue while you travel.".
    Requires able(actor) and at(actor, origin) and route(origin, destination) and not closed(destination) and not denied(actor, origin, destination).
    On success { Assert at(actor, destination). }
  }
  Action walk(actor: group, origin: place, destination: place) "Walk the footpath to {destination}" {
    Requires able(actor) and at(actor, origin) and unladen(actor) and footway(origin, destination).
    On success { Assert at(actor, destination). }
  }
  Action cross(actor: group, origin: place, destination: place, defender: group) "Cross past {defender} to {destination}" {
    Requires able(actor) and at(actor, origin) and gate(defender, origin, destination)
      and (released(defender) or not able(defender)) and not closed(destination).
    On success { Assert at(actor, destination). }
  }
  Action pay(actor: group, recipient: group, site: place) "Give {recipient} one coin" {
    Result "You hand over one coin. It is now in the recipient\u2019s purse.".
    Requires able(actor) and able(recipient) and distinct(actor, recipient) and at(actor, site) and at(recipient, site)
      and quantity(actor, gold) >= 1.
    On success { Decrease quantity(actor, gold) by 1. Increase quantity(recipient, gold) by 1.
      Increase received(recipient) by 1. }
  }
  Action give_food(actor: group, recipient: group, site: place) "Give {recipient} one ration" {
    Result "You offer a ration and step back. The recipient now owns it; what they do next is their decision.".
    Requires able(actor) and able(recipient) and distinct(actor, recipient) and at(actor, site) and at(recipient, site)
      and quantity(actor, rations) >= 1.
    On success { Decrease quantity(actor, rations) by 1. Increase quantity(recipient, rations) by 1. }
  }
  Action eat(actor: group) "Eat a ration" {
    Result "The company shares a ration. This satisfies hunger but does not restore health or mana.".
    Requires able(actor) and not sated(actor) and quantity(actor, rations) >= 1.
    On success { Decrease quantity(actor, rations) by 1. Assert sated(actor). }
  }
  Action release(actor: group) "End the blockade" {
    Requires able(actor) and gatekeeper(actor) and not released(actor) and releaseAllowed(actor).
    On success { Assert released(actor). }
  }
  Action collect(actor: group, store: stock, goods: good, site: place) "Collect one {goods} from {store}" {
    Result "You collect one unit from the available stock. It is now carried by the company.".
    Requires able(actor) and at(actor, site) and at(store, site) and mayCollect(actor, store)
      and unladen(actor) and quantity(store, goods) >= 1.
    On success { Decrease quantity(store, goods) by 1. Retract unladen(actor). Assert carrying(actor, goods). }
  }
  Action put(actor: group, store: stock, goods: good, site: place) "Deposit one {goods} in {store}" {
    Result "You deposit what the company was carrying. The stock increases and your hands are free.".
    Requires able(actor) and at(actor, site) and at(store, site) and carrying(actor, goods).
    On success { Retract carrying(actor, goods). Assert unladen(actor). Increase quantity(store, goods) by 1. }
  }
  Action fulfill_job(actor: group, store: stock, goods: good, site: place) "Deliver {goods} to {store} for pay" {
    Requires able(actor) and at(actor, site) and at(store, site) and carrying(actor, goods)
      and job(store, goods) and quantity(store, gold) >= 1.
    On success { Retract carrying(actor, goods). Assert unladen(actor). Increase quantity(store, goods) by 1.
      Decrease quantity(store, gold) by 1. Increase quantity(actor, gold) by 1. }
  }
  Action attack(actor: group, opponent: group, site: place) "Attack {opponent}" {
    Requires able(actor) and able(opponent) and distinct(actor, opponent) and at(actor, site) and at(opponent, site).
    Resolve combat(opponent).
    On success { Assert hostile(actor, opponent). Assert hostile(opponent, actor). }
    On failure { Assert hostile(actor, opponent). Assert hostile(opponent, actor). }
  }
}

data/rulesets/affinities.kyr:
Module affinities "Recognized company and receptive wildlife" {
  Kind capability.
  Relation capable(group, capability).
  Relation recognizes(group, capability).
  Relation receptive(group, capability).
  Goal false.
  Action request_passage(actor: group, keeper: group, identity: capability, site: place) "Request passage from {keeper} as {identity}" {
    Result "You invoke the compact. The keeper honors your company\u2019s standing and grants passage.".
    Description "Invoke a company identity this keeper has explicitly agreed to honor. This is not general persuasion.".
    Requires able(actor) and able(keeper) and distinct(actor, keeper) and at(actor, site) and at(keeper, site)
      and recognizes(keeper, identity) and capable(actor, identity) and not released(keeper).
    On success { Assert released(keeper). }
  }
  Action approach_wildlife(actor: group, animal: group, skill: capability, site: place) "Approach {animal} using {skill}" {
    Result "You read the animal\u2019s signals and approach without provoking it. The guarded route is now available.".
    Description "Read the signals of an explicitly receptive animal and pass without provoking it. Hostile animals cannot be approached this way.".
    Requires able(actor) and able(animal) and distinct(actor, animal) and at(actor, site) and at(animal, site)
      and receptive(animal, skill) and capable(actor, skill) and not hostile(animal, actor) and not released(animal).
    On success { Assert released(animal). }
  }
}

data/rulesets/discovery.kyr:
Module discovery_rules "Reliable discovery and trusted reports" {
  Kind fact. Kind source.
  Relation established(fact).
  Relation reveals(source, fact).
  Relation intact(source).
  Relation noticeable(source).
  Relation destructible(source).
  Relation mayExamine(group, source).
  Relation knows(group, fact).
  Relation assumesFalse(group, fact).
  Relation trusts(group, group).
  Relation learnedFrom(group, source, fact).
  Relation toldBy(group, group, fact).
  Relation publicPlace(place).
  Relation testimony(group, source).
  Goal false.
  Action examine(actor: group, witness: source, statement: fact, site: place) "Examine {witness}" {
    Requires able(actor) and at(actor, site) and at(witness, site)
      and noticeable(witness) and intact(witness) and mayExamine(actor, witness)
      and reveals(witness, statement) and established(statement) and not learnedFrom(actor, witness, statement).
    On success {
      Assert knows(actor, statement). Retract assumesFalse(actor, statement).
      Assert learnedFrom(actor, witness, statement).
    }
  }
  Action tell(actor: group, recipient: group, statement: fact, site: place) "Tell {recipient}: {statement}" {
    Result "You explain what the evidence establishes. The listener accepts your account and sets aside a conflicting assumption; their next choices remain their own.".
    Requires able(actor) and able(recipient) and distinct(actor, recipient)
      and at(actor, site) and at(recipient, site) and trusts(recipient, actor)
      and knows(actor, statement) and established(statement) and not toldBy(recipient, actor, statement).
    On success {
      Assert knows(recipient, statement). Retract assumesFalse(recipient, statement).
      Assert toldBy(recipient, actor, statement).
    }
  }
  Action ask(actor: group, informant: group, topic: source, statement: fact, site: place) "Ask {informant} about {topic}" {
    Result "The speaker shares an account they know. You record it in your journal.".
    Description "Ask about an offered topic. The speaker shares an established fact they actually know.".
    Requires able(actor) and able(informant) and distinct(actor, informant)
      and at(actor, site) and at(informant, site) and testimony(informant, topic)
      and reveals(topic, statement) and noticeable(topic)
      and knows(informant, statement) and established(statement) and not toldBy(actor, informant, statement).
    On success {
      Assert knows(actor, statement). Retract assumesFalse(actor, statement).
      Assert toldBy(actor, informant, statement).
    }
  }
  Action destroy_source(actor: group, witness: source, site: place) "Destroy {witness}" {
    Result "You destroy this source of evidence. Existing knowledge and other sources remain.".
    Requires able(actor) and at(actor, site) and at(witness, site)
      and noticeable(witness) and intact(witness) and destructible(witness).
    On success { Retract intact(witness). }
  }
}

data/rulesets/dungeoneering.kyr:
Module dungeoneering "Physical obstructions, warnings and custody" {
  Kind hazard. Kind districtkind.
  Relation district(place, districtkind).
  Relation townDistrict(districtkind). Relation wildernessDistrict(districtkind). Relation undergroundDistrict(districtkind).
  Measure encounterXp(group).
  Relation hazardPassage(hazard, place, place).
  Relation armed(hazard). Relation triggered(hazard).
  Relation hazardEffect(hazard, ability). Relation warning(hazard, fact).
  Relation obstruction(mechanism). Relation trapped(group). Relation restrainedBy(group, mechanism).
  Relation home(group, place). Relation rescued(group).
  Relation climbingPassage(place, place).
  Relation acceptsCustody(group). Relation requiresRecord(group, fact).
  Relation custodyGranted(group, group).
  Relation custodyWrit(group).
  Relation soldRecord(group). Relation deliveredBearing(group).
  Relation forageStock(stock).
  Relation commissions(group, item). Relation commissionPaid(group, item).
  Goal false.
  Action fulfill_commission(actor: group, buyer: group, cargo: item, carrier: member, receiver: member, site: place) "Deliver {cargo} to {buyer} for six coins" {
    Requires able(actor) and able(buyer) and distinct(actor, buyer) and at(actor, site) and at(buyer, site)
      and commissions(buyer, cargo) and not commissionPaid(buyer, cargo) and quantity(buyer, gold) >= 6
      and memberOf(carrier, actor) and ownedItem(cargo, carrier) and memberOf(receiver, buyer) and awake(receiver).
    Resolve transfer_item(cargo, carrier, receiver).
    On success { Decrease quantity(buyer, gold) by 6. Increase quantity(actor, gold) by 6. Assert commissionPaid(buyer, cargo). }
    Result "The buyer takes actual possession of the commissioned object and pays six coins from their finite purse. The company no longer carries it.".
  }
  Action forage(actor: group, patch: stock, site: place) "Gather an edible ration from {patch}" {
    Requires able(actor) and at(actor, site) and at(patch, site) and forageStock(patch)
      and capable(actor, woodcraft) and quantity(patch, rations) >= 1.
    Time 2.
    On success { Decrease quantity(patch, rations) by 1. Increase quantity(actor, rations) by 1. }
    Result "Your woodcraft specialist gathers a shared ration from the identified edible patch. The finite patch is reduced; it does not replenish when you revisit.".
  }
  Action risk_passage(actor: group, trap: hazard, origin: place, destination: place, blow: ability, victim: member) "Risk {trap} toward {destination}; {victim} leads" {
    Requires able(actor) and at(actor, origin) and hazardPassage(trap, origin, destination) and armed(trap)
      and hazardEffect(trap, blow) and memberOf(victim, actor) and awake(victim).
    Resolve expose(blow, victim).
    On success { Retract armed(trap). Assert triggered(trap). Assert at(actor, destination). }
    On failure { Retract armed(trap). Assert triggered(trap). }
    Result "The leading companion tests the dangerous crossing. Its mechanism discharges once; the injuries and spent mechanism remain.".
  }
  Action cleared_passage(actor: group, trap: hazard, origin: place, destination: place) "Cross the spent {trap} toward {destination}" {
    Requires able(actor) and at(actor, origin) and hazardPassage(trap, origin, destination) and not armed(trap).
    On success { Assert at(actor, destination). }
    Result "You cross the now-spent mechanism. It will not rearm when you return.".
  }
  Action disarm(actor: group, trap: hazard, origin: place, destination: place, clue: fact) "Disarm {trap}" {
    Requires able(actor) and at(actor, origin) and hazardPassage(trap, origin, destination) and armed(trap)
      and warning(trap, clue) and knows(actor, clue) and capable(actor, delving).
    Time 2.
    On success { Retract armed(trap). }
    Result "Your delving specialist identifies the warned release and pins it safely. The spent mechanism stays disabled.".
  }
  Action brace(actor: group, trap: hazard, origin: place, destination: place, clue: fact, kit: item, bearer: member) "Brace {trap} with {kit}" {
    Requires able(actor) and at(actor, origin) and hazardPassage(trap, origin, destination) and armed(trap)
      and warning(trap, clue) and knows(actor, clue) and memberOf(bearer, actor) and awake(bearer)
      and ownedItem(kit, bearer) and wearing(kit, bearer) and itemKind(kit, ropekit).
    Time 2.
    On success { Retract armed(trap). }
    Result "Following the warning, you pin and brace the moving parts with the climbing kit. This crossing remains safe. The reusable kit stays with its bearer.".
  }
  Action climb(actor: group, origin: place, destination: place, kit: item, bearer: member) "Climb to {destination} using {kit}" {
    Requires able(actor) and at(actor, origin) and climbingPassage(origin, destination)
      and memberOf(bearer, actor) and awake(bearer) and ownedItem(kit, bearer) and wearing(kit, bearer) and itemKind(kit, ropekit).
    Time 2.
    On success { Assert at(actor, destination). }
    Result "The company anchors its line and climbs together. The kit opens this route without changing the underlying geography.".
  }
  Action free_obstruction(actor: group, companion: group, device: mechanism, site: place) "Shift {device} to free {companion}" {
    Requires able(actor) and able(companion) and at(actor, site) and at(companion, site) and trapped(companion)
      and restrainedBy(companion, device) and mounted(device, site) and obstruction(device).
    Time 2.
    On success { Retract trapped(companion). Assert rescued(companion). }
    Result "You lever the obstruction aside. The trapped person is free, but still needs a safe route home.".
  }
  Action escort(actor: group, companion: group, origin: place, destination: place) "Escort {companion} to {destination}" {
    Requires able(actor) and able(companion) and distinct(actor, companion) and at(actor, origin) and at(companion, origin)
      and rescued(companion) and not trapped(companion) and not home(companion, origin)
      and route(origin, destination) and not closed(destination) and not denied(actor, origin, destination).
    On success { Assert at(actor, destination). Assert at(companion, destination). }
    Result "You travel together. Your companion remains at the actual destination; no one teleports home.".
  }
  Action request_custody(actor: group, keeper: group, statement: fact, site: place) "Present the register and custody writ to {keeper}" {
    Requires able(actor) and able(keeper) and distinct(actor, keeper) and at(actor, site) and at(keeper, site)
      and acceptsCustody(keeper) and requiresRecord(keeper, statement) and knows(actor, statement)
      and custodyWrit(actor) and not custodyGranted(keeper, actor).
    On success { Assert custodyGranted(keeper, actor). Assert released(keeper). }
    Result "The keeper checks the named record and your custody writ. It allows passage under that authority. It remains alive, and the dead have not become ownerless loot.".
  }
}

data/rulesets/ecology.kyr:
Module ecology "Habitat signs and finite herbal gathering" {
  Kind species.
  Relation habitatSpecies(place, species).
  Relation signsOf(place, species).
  Relation recognized(group, species).
  Relation harvestable(item, species).
  Goal false.
  Action identify_species(actor: group, life: species, site: place) "Read the signs of {life}" {
    Description "A living woodcraft specialist identifies an authored species from signs in its declared habitat. This is identification, not a simulation of an ecosystem.".
    Requires able(actor) and at(actor, site) and habitatSpecies(site, life) and signsOf(site, life)
      and capable(actor, woodcraft) and not recognized(actor, life).
    On success { Assert recognized(actor, life). }
    Result "Your trail-wise companion identifies the species from its signs. Suitable resources here can now be gathered carefully.".
  }
  Action gather_herb(actor: group, herb: item, life: species, form: itemkind, recipient: member, site: place) "Gather {herb} for {recipient}" {
    Description "Collect a finite, authored herbal preparation. It does not regrow merely because you leave.".
    Requires able(actor) and at(actor, site) and habitatSpecies(site, life) and recognized(actor, life)
      and harvestable(herb, life) and at(herb, site) and itemKind(herb, form)
      and memberOf(recipient, actor) and awake(recipient) and capable(actor, woodcraft).
    Resolve acquire(herb, form, recipient).
    On success { Retract at(herb, site). }
    Result "You gather and dress the usable stems into one poultice. The patch is depleted; its preparation is now a real, single-use carried item.".
  }
