data/rulesets/expedition.kyr:
Module expedition "Finite supplies and salvage" {
  Relation offers(group, good).
  Relation salvage(stock).
  Goal false.
  Action buy(actor: group, merchant: group, goods: good, site: place) "Buy one {goods} from {merchant} for two coins" {
    Description "Trade two coins for one unit from a present merchant's finite stock. This is a posted price, not a negotiation simulation.".
    Requires able(actor) and able(merchant) and distinct(actor, merchant) and at(actor, site) and at(merchant, site)
      and offers(merchant, goods) and quantity(merchant, goods) >= 1 and quantity(actor, gold) >= 2.
    On success { Decrease quantity(actor, gold) by 2. Increase quantity(merchant, gold) by 2.
      Decrease quantity(merchant, goods) by 1. Increase quantity(actor, goods) by 1. }
    Result "You pay two coins and receive one unit of supplies. The merchant's stock and both purses change accordingly.".
  }
  Action salvage_coin(actor: group, store: stock, site: place) "Recover a coin from {store}" {
    Requires able(actor) and at(actor, site) and at(store, site) and salvage(store) and quantity(store, gold) >= 1.
    On success { Decrease quantity(store, gold) by 1. Increase quantity(actor, gold) by 1. }
    Result "You recover one coin from the finite cache. It is now in the company's purse.".
  }
}

data/rulesets/fieldcraft.kyr:
Module fieldcraft "Preparation, field magic and lasting rewards" {
  Kind member. Kind ability. Kind reward.
  Relation memberOf(member, group).
  Relation fieldUsable(ability).
  Relation awake(member). Relation needsCare(member). Relation canCast(member, ability). Relation treatable(member, ability).
  Relation restful(place). Relation offeredAt(reward, place). Relation giftEffect(reward, ability).
  Relation rewardFor(reward, fact). Relation claimed(reward).
  Goal false.
  Action field_spell(actor: group, caster: member, technique: ability, recipient: member, site: place) "Have {caster} use {technique} on {recipient}" {
    Description "Use a known healing or cleansing ability outside combat. Its normal mana cost is paid; combat cooldowns do not apply.".
    Requires able(actor) and at(actor, site) and memberOf(caster, actor) and memberOf(recipient, actor)
      and fieldUsable(technique) and awake(caster) and awake(recipient) and needsCare(recipient) and canCast(caster, technique) and treatable(recipient, technique).
    Resolve invoke(technique, caster, recipient).
    Result "You pause to tend a companion. The same spell effects and mana costs apply here as in battle.".
  }
  Action rest(actor: group, site: place) "Rest and recover at {site}" {
    Description "Spend six hours and one shared ration at a safe shelter. Living companions recover HP and mana; bleeding is treated. Poison and death remain. Other people and deadlines continue.".
    Requires able(actor) and at(actor, site) and restful(site) and quantity(actor, rations) >= 1.
    Time 36. Resolve recover(actor).
    On success { Decrease quantity(actor, rations) by 1. }
    Result "You settle in for six hours, sharing a ration and tending your wounds. The world continues outside.".
  }
  Action learn_reward(actor: group, gift: reward, recipient: member, lesson: ability, proof: fact, site: place) "Accept {gift} for {recipient}" {
    Requires able(actor) and at(actor, site) and offeredAt(gift, site) and memberOf(recipient, actor)
      and awake(recipient) and giftEffect(gift, lesson) and rewardFor(gift, proof) and knows(actor, proof)
      and not claimed(gift).
    Resolve reward(lesson, recipient).
    On success { Assert claimed(gift). Retract offeredAt(gift, site). Retract at(gift, site). }
    Result "The chosen companion studies the one-use lesson. Its power is spent, but the learned ability remains available on future expeditions.".
  }
}

data/rulesets/items.kyr:
Module items "Equipment, consumables and training" {
  Kind item. Kind itemkind.
  Relation itemKind(item, itemkind). Relation ownedItem(item, member). Relation wearing(item, member).
  Relation forSale(item). Relation soldBy(item, group) exclusive. Relation wearable(itemkind). Relation consumable(itemkind).
  Relation canTrain(member, ability). Relation teaches(group, ability).
  Measure price(item).
  Goal false.
  Action take_item(actor: group, find: item, form: itemkind, recipient: member, site: place) "Collect {find} for {recipient}" {
    Requires able(actor) and at(actor, site) and at(find, site) and not forSale(find)
      and itemKind(find, form) and memberOf(recipient, actor) and awake(recipient).
    Resolve acquire(find, form, recipient).
    On success { Retract at(find, site). }
    Result "The item is now carried by the chosen companion. It will remain with them between expeditions.".
  }
  Action buy_item(actor: group, find: item, form: itemkind, recipient: member, merchant: group, site: place) "Buy {find} for {recipient}" {
    Requires able(actor) and at(actor, site) and at(find, site) and forSale(find) and itemKind(find, form)
      and memberOf(recipient, actor) and awake(recipient) and soldBy(find, merchant)
      and able(merchant) and at(merchant, site) and distinct(actor, merchant) and quantity(actor, gold) >= price(find).
    Resolve purchase(find, form, recipient, actor, merchant).
    On success { Retract at(find, site). Retract forSale(find). }
    Result "You pay the posted price and take possession of the item. This finite stock is not replaced when you return.".
  }
  Action equip_item(actor: group, tool: item, form: itemkind, wearer: member) "Equip {tool} on {wearer}" {
    Requires able(actor) and memberOf(wearer, actor) and awake(wearer) and ownedItem(tool, wearer)
      and itemKind(tool, form) and wearable(form) and not wearing(tool, wearer).
    Resolve equip(tool, wearer).
    Result "The companion equips the item. Another item in the same slot is put away; generated characteristics stay unchanged.".
  }
  Action use_item(actor: group, dose: item, form: itemkind, carrier: member, recipient: member) "Use {dose} on {recipient}" {
    Requires able(actor) and memberOf(carrier, actor) and memberOf(recipient, actor) and awake(carrier)
      and awake(recipient) and ownedItem(dose, carrier) and itemKind(dose, form) and consumable(form).
    Resolve consume(dose, carrier, recipient).
    Result "The single dose is spent. Its effects resolve on the chosen companion.".
  }
  Action transfer_item(actor: group, cargo: item, carrier: member, recipient: member) "Give {cargo} to {recipient}" {
    Requires able(actor) and memberOf(carrier, actor) and memberOf(recipient, actor)
      and not ownedItem(cargo, recipient) and awake(recipient) and ownedItem(cargo, carrier).
    Resolve transfer_item(cargo, carrier, recipient).
    Result "The companion takes the item and packs it away. Equipment can also be recovered from fallen companions.".
  }
  Action put_item(actor: group, cargo: item, carrier: member, site: place) "Set down {cargo}" {
    Requires able(actor) and at(actor, site) and memberOf(carrier, actor) and awake(carrier) and ownedItem(cargo, carrier).
    Resolve drop(cargo, carrier).
    On success { Assert at(cargo, site). }
    Result "You leave the object here. Its position persists until somebody moves it.".
  }
  Action train_member(actor: group, mentor: group, student: member, lesson: ability, site: place) "Train {student} in {lesson}" {
    Requires able(actor) and able(mentor) and distinct(actor, mentor) and at(actor, site) and at(mentor, site)
      and memberOf(student, actor) and awake(student) and teaches(mentor, lesson) and canTrain(student, lesson).
    Resolve train(lesson, student).
    Time 6.
    Result "An hour of instruction spends 20 earned experience. The learned technique remains available on future expeditions.".
  }
}

data/rulesets/site-capabilities.kyr:
Module site_capabilities "Places, commitments and mechanisms" {
  Kind mechanism.
  Relation functioning(mechanism).
  Relation mounted(mechanism, place).
  Relation barrier(mechanism, place).
  Relation operates(group, mechanism).
  Relation keyedBy(mechanism, group).
  Relation supports(group, group).
  Relation seeksBacking(group).
  Relation mandate(group, place).
  Relation controlled(place, group) exclusive.
  Relation informedPassage(place, place, fact).
  Measure enforceAt(group).
  Goal false.
  Action take_control(actor: group, device: mechanism, keeper: group, site: place) "Take the key for {device} from {keeper}" {
    Result "You recover the keeper\u2019s key. You can now operate the mechanism; it has not opened by itself.".
    Description "Recover access from an incapacitated keeper here. You must still operate the mechanism yourself.".
    Requires able(actor) and not able(keeper) and at(actor, site) and at(keeper, site)
      and mounted(device, site) and keyedBy(device, keeper) and not operates(actor, device).
    On success { Assert operates(actor, device). }
  }
  Action endorse(actor: group, recipient: group, site: place) "Pledge support to {recipient}" {
    Description "Publicly put your name behind this person's claim.".
    Requires able(actor) and able(recipient) and distinct(actor, recipient) and at(actor, site)
      and at(recipient, site) and seeksBacking(recipient) and not supports(actor, recipient).
    On success { Assert supports(actor, recipient). }
  }
  Action enforce(actor: group, site: place) "Establish control of {site}" {
    Requires able(actor) and at(actor, site) and mandate(actor, site) and not controlled(site, actor)
      and watch(clock) >= enforceAt(actor).
    On success { Assert controlled(site, actor). }
  }
  Action disable(actor: group, device: mechanism, site: place) "Disable {device}" {
    Result "You dismantle the operating mechanism. It stops; any earlier damage remains.".
    Description "Dismantle an accessible mechanism you are equipped to work on. The change persists.".
    Requires able(actor) and at(actor, site) and mounted(device, site) and operates(actor, device)
      and functioning(device).
    On success { Retract functioning(device). }
  }
  Action shut(actor: group, device: mechanism, site: place, destination: place) "Close {device}" {
    Result "You close the barrier. People already beyond it can leave.".
    Description "Close the passage this mechanism controls. People already inside can leave.".
    Requires able(actor) and at(actor, site) and mounted(device, site) and barrier(device, destination)
      and operates(actor, device) and not closed(destination).
    On success { Assert closed(destination). }
  }
  Action open(actor: group, device: mechanism, site: place, destination: place) "Open {device}" {
    Result "You open the barrier. The passage beyond is now available, though it may still be dangerous.".
    Description "Reopen the physical passage. This does not make the place beyond it safe.".
    Requires able(actor) and at(actor, site) and mounted(device, site) and barrier(device, destination)
      and operates(actor, device) and closed(destination).
    On success { Retract closed(destination). }
  }
  Action passage(actor: group, origin: place, destination: place, statement: fact) "Follow the concealed passage to {destination}" {
    Result "You follow the route you learned about and emerge beyond the obstruction.".
    Requires able(actor) and at(actor, origin) and informedPassage(origin, destination, statement)
      and knows(actor, statement) and not closed(destination).
    On success { Assert at(actor, destination). }
  }
}

data/rulesets/spatial.kyr:
